  'prompt.video-turn.title': 'Golden turn',
  'prompt.video-turn.description': 'On a rooftop at golden hour, she turns and smiles.',
  'prompt.video-turn.text': 'Create a video: a young woman on a rooftop turns from the skyline to face the camera and smiles, her hair lifting in the wind. Camera: slow push from medium shot to close-up, 50mm, shallow depth of field, 4 seconds. Light: low golden-hour sun raking across her face, warm rim light, soft shadows. Style: natural and editorial, real skin texture, fine film grain, silent; no text, no watermark.',
  'prompt.video-coast.title': 'Coastline reveal',
